<?php
$fmtMass=static fn($v): string => number_format((float)$v,3,',',' ');
$fmtMoney=static fn($v): string => number_format((float)$v,2,',',' ');
$fmtDate=static function($v): string { $t=$v?strtotime((string)$v):false; return $t===false?'—':date('d.m.Y H:i',$t); };
$typeLabel=static fn(string $type): string => match($type){'rate_34_5'=>'34,5','rate_38'=>'38',default=>'Согласование'};
?>
